using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.AspNetCore.Http;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddLogging();

var app = builder.Build()

// Simple in-memory product store
var products = new List<Product>
{
    new Product(1, "Apple"),
    new Product(2, "Banana"),
    new Product(3, "Orange")
};

// Create a route group for /api/v1/products
var productGroup = app.MapGroup("/api/v1/products");

// Endpoint filter to log each call
productGroup.AddEndpointFilter(async (context, next) =>
{
    var logger = context.HttpContext.RequestServices.GetRequiredService<ILoggerFactory>()
        .CreateLogger("ProductsEndpoint");
    logger.LogInformation("Handling {Method} {Path}",
        context.HttpContext.Request.Method,
        context.HttpContext.Request.Path);
    return await next(context);
});

// GET /api/v1/products - list all products
productGroup.MapGet("/", () => products);

// GET /api/v1/products/{id} - get product by id
productGroup.MapGet("/{id:int}", (int id) =>
{
    var product = products.FirstOrDefault(p => p.Id == id);
    return product is not null ? Results.Ok(product) : Results.NotFound();
});

app.Run();

